import React, { useEffect, useState } from "react";
import styles from './SearchPopup.module.css';
import { DateRange } from "react-date-range";
import "react-date-range/dist/styles.css"; // Main CSS file for react-date-range
import "react-date-range/dist/theme/default.css";

const SearchPopup = ({ onSearch }) => {
  const [formData, setFormData] = useState({
    destination: '',
    checkin_date: '',
    min_price: '',
    max_price: '',
    adults: '',
    children: '',
    room: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSearch(formData);
  };

  return (
  <aside className={styles['search-popup']}>
    <h3 className={styles['search-popup__title']}>Search</h3>
    <form className={styles['search-popup__form']} onSubmit={handleSubmit}>
      <div className={styles['form-group']}>
        <label htmlFor="destination">Destination</label>
        <input type="text" id="destination" placeholder="Destination" name="destination"
               value={formData.destination} onChange={handleChange} />
      </div>

      <div className={styles['form-group']}>
        <label htmlFor="checkin">Check-in Date</label>
        {/*<input type="text" id="checkin" name="checkin_date" defaultValue="06/24/2022 to 06/24/2022"*/}
        {/*       value={formData.checkin_date}*/}
        {/*       onChange={handleChange}*/}
        {/* />*/}
        <input
            placeholder={`${dateRange[0].startDate.toLocaleDateString()} to ${dateRange[0].endDate.toLocaleDateString()}`}
            aria-label="Date range"
            onClick={() => setShowDatePicker(!showDatePicker)}
            readOnly
        />
        {showDatePicker && (
            <div ref={datePickerRef}>
              <DateRange
                  editableDateInputs={true}
                  moveRangeOnFirstSelection={false}
                  className="date-range-picker"
                  minDate={new Date()}
                  onChange={handleDateSelect}
                  ranges={dateRange}
              />
            </div>
        )}
      </div>

      <fieldset className={styles['form-group']}>
        <legend>Options</legend>
        <div className={styles['form-inline']}>
          <label htmlFor="min-price">Min price per night</label>
          <input type="number" id="min-price" name="min_price" value={formData.min_price}
                 onChange={handleChange}
          />
        </div>
        <div className={styles['form-inline']}>
          <label htmlFor="max-price">Max price per night</label>
          <input type="number" id="max-price" name="max_price"  value={formData.max_price} onChange={handleChange}
          />
        </div>
        <div className={styles['form-inline']}>
          <label htmlFor="adults">Adult</label>
          <input type="number" id="adults" name="adults" defaultValue={1} min="1" value={formData.adults} onChange={handleChange}
          />
        </div>
        <div className={styles['form-inline']}>
          <label htmlFor="children">Children</label>
          <input type="number" id="children" name="children" defaultValue={0} min="0" value={formData.children} onChange={handleChange}
          />
        </div>
        <div className={styles['form-inline']}>
          <label htmlFor="rooms">Room</label>
          <input type="number" id="rooms" name="rooms" defaultValue={1} min="1"
                 value={formData.room}
                 onChange={handleChange}
           />
        </div>
      </fieldset>

      <button type="submit" className={styles['search-popup__button']}>Search</button>
    </form>
  </aside>

);
};

export default SearchPopup;
